    {
        sealed class LexiconData
        {
            internal readonly HashSet<string> Words = new HashSet<string>(StringComparer.Ordinal);
            internal readonly HashSet<string> Prefixes = new HashSet<string>(StringComparer.Ordinal);
            internal readonly HashSet<string> Vietnamese = new HashSet<string>(StringComparer.Ordinal);
