        static volatile LexiconData data = Build();
        internal static string DirectoryPath { get { return AppDomain.CurrentDomain.BaseDirectory; } }
        internal static string EnglishPath { get { return Path.Combine(DirectoryPath, "EnglishWords.txt"); } }
        internal static string VietnamesePath { get { return Path.Combine(DirectoryPath, "VietnameseOverrides.txt"); } }
        static bool IsAsciiWord(string word)
        {
            if (string.IsNullOrEmpty(word) || word.Length > 64) return false;
            foreach (char c in word) if (c < 'a' || c > 'z') return false;
            return true;
        }
        static void Add(LexiconData result, string word)
        {
            word = word.Trim().ToLowerInvariant();
            if (!IsAsciiWord(word) || !result.Words.Add(word)) return;
            for (int i=1; i<word.Length; i++) result.Prefixes.Add(word.Substring(0, i));
        }
        static void ReadWords(string file, Action<string> add)
        {
            try {
                if (!File.Exists(file)) return;
                foreach(string line in File.ReadAllLines(file, Encoding.UTF8)) {
                    string word=line.Trim().ToLowerInvariant();
                    if(word.Length==0 || word[0]=='#') continue;
                    add(word);
                }
            }
            catch(IOException) { /* No disk dependency for normal typing. */ }
            catch(UnauthorizedAccessException) { }
        }
        static LexiconData Build()
        {
            var result=new LexiconData();
            foreach(string word in CoreWords.Split(new[]{' ','\r','\n','\t'},StringSplitOptions.RemoveEmptyEntries)) Add(result,word);
            ReadWords(EnglishPath,word => Add(result,word));
            ReadWords(VietnamesePath,word => { if(IsAsciiWord(word)) result.Vietnamese.Add(word); });
            return result;
        }
        internal static void Reload() { data=Build(); }
        internal static bool HasPrefix(string text)
        {
            string w=text.ToLowerInvariant();
            var snapshot=data;
            return IsAsciiWord(w) && !snapshot.Vietnamese.Contains(w) &&
                   (snapshot.Words.Contains(w) || snapshot.Prefixes.Contains(w));
        }
        internal static bool IsWord(string text)
        {
            string w=text.ToLowerInvariant();
            var snapshot=data;
            return IsAsciiWord(w) && !snapshot.Vietnamese.Contains(w) && snapshot.Words.Contains(w);
        }
        internal static bool PreferVietnamese(string text) { return data.Vietnamese.Contains(text.ToLowerInvariant()); }
        internal static int WordCount { get { return data.Words.Count; } }
